 position(){return Math.min(this.duration,this.offset+(this.playing?(this.context.currentTime-this.anchor)*this.rate:0));}
 start(){if(!this.context||this.context.state!=='running')return false;if(this.offset>=this.duration-.025)this.offset=this.loop?.[0]||0;if(this.loop&&(this.offset<this.loop[0]||this.offset>=this.loop[1]))this.offset=this.loop[0];this.anchor=this.context.currentTime;this.cursor=lowerBound(this.notes,this.offset-.01);this.lastBeat=-1;this.playing=true;this.schedule();return true;}
