 schedule(){if(!this.playing)return;let p=this.position();const end=this.loop?.[1]??this.duration;if(p>=end){if(this.loop||this.repeat){this.seek(this.loop?.[0]||0);return;}this.pause();this.offset=0;this.onEnd?.();return;}const until=Math.min(end,p+.16*this.rate);while(this.cursor<this.notes.length&&this.notes[this.cursor][0]<until){const n=this.notes[this.cursor++];if(n[0]>=p-.06&&this.accepts(n))this.note(n[1],this.context.currentTime+Math.max(0,(n[0]-p)/this.rate),Math.min(n[2],end-n[0])/this.rate,n[3],{string:this.instrument==='guitar'?n[4]:null});}
  if(this.metronome){const beatLength=60/this.bpm;const tick=Math.floor((p-.15)/beatLength)+1;if(tick!==this.lastBeat&&tick>=0){const when=.15+tick*beatLength;if(when<until){this.lastBeat=tick;this.click(this.context.currentTime+Math.max(0,(when-p)/this.rate),tick%this.beats===0);}}}
 }
 note(midi,time,duration,velocity=.7,meta={}){let nearest=60,delta=Infinity;for(const n of this.samples.keys())if(Math.abs(n-midi)<delta){nearest=n;delta=Math.abs(n-midi);}const buffer=this.samples.get(nearest);if(!buffer||!this.context)return;const source=this.context.createBufferSource();source.buffer=buffer;source.playbackRate.value=2**((midi-nearest)/12);const gain=this.context.createGain();const amp=(this.instrument==='guitar'?.42:.25)*Math.pow(Math.max(.16,velocity),1.25),hold=Math.max(.025,duration);gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(amp,time+.005);gain.gain.setValueAtTime(amp,time+hold);gain.gain.exponentialRampToValueAtTime(.0001,time+hold+(this.instrument==='guitar'?.35:.9));source.connect(gain);gain.connect(this.dry);gain.connect(this.reverb);
  if(meta.string!=null)for(const voice of this.voices)if(voice.string===meta.string){try{voice.gain.gain.setTargetAtTime(0,time,.008);voice.source.stop(time+.04);}catch{}}
  const voice={source,gain,string:meta.string};this.voices.add(voice);source.onended=()=>{this.voices.delete(voice);source.disconnect();gain.disconnect();};source.start(time);source.stop(time+hold+1);return voice;
 }
 release(voice){if(!voice||!this.context)return;const t=this.context.currentTime;try{voice.gain.gain.cancelScheduledValues(t);voice.gain.gain.setTargetAtTime(0,t,.025);voice.source.stop(t+.16);}catch{}}
 click(time,strong){if(!this.context.createOscillator)return;const o=this.context.createOscillator(),g=this.context.createGain();o.frequency.value=strong?1200:800;g.gain.setValueAtTime(.08,time);g.gain.exponentialRampToValueAtTime(.001,time+.045);o.connect(g);g.connect(this.master);o.start(time);o.stop(time+.05);}
 eventsAt(time=this.position()){const events=[];const end=lowerBound(this.notes,time+.025);for(let i=Math.max(0,end-160);i<end;i++){const n=this.notes[i];if(n[0]<=time+.015&&n[0]+n[2]>time&&this.accepts(n))events.push(n);}return events;}
 activeNotes(){return this.playing?this.eventsAt().map(n=>n[1]):[];}
